package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"
)

type CircuitState int32

const (
	StateClosed CircuitState = iota
	StateOpen
	StateHalfOpen
)

type CircuitBreaker struct {
	state     int32
	failures  int32
	threshold int32
	resetTime time.Duration
	lastFail  time.Time
	mu        sync.Mutex
}

func NewCircuitBreaker(threshold int32, resetTime time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:     int32(StateClosed),
		threshold: threshold,
		resetTime: resetTime,
	}
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
	state := CircuitState(atomic.LoadInt32(&cb.state))
	if state == StateOpen {
		cb.mu.Lock()
		if time.Since(cb.lastFail) > cb.resetTime {
			atomic.StoreInt32(&cb.state, int32(StateHalfOpen))
			cb.mu.Unlock()
		} else {
			cb.mu.Unlock()
			return fmt.Errorf("circuit breaker open")
		}
	}
	err := fn()
	if err != nil {
		cb.recordFailure()
		return err
	}
	atomic.StoreInt32(&cb.state, int32(StateClosed))
	atomic.StoreInt32(&cb.failures, 0)
	return nil
}

func (cb *CircuitBreaker) recordFailure() {
	newFails := atomic.AddInt32(&cb.failures, 1)
	if newFails >= cb.threshold {
		atomic.StoreInt32(&cb.state, int32(StateOpen))
		cb.mu.Lock()
		cb.lastFail = time.Now()
		cb.mu.Unlock()
	}
}

type LogAgent struct {
	baseDir   string
	cb        *CircuitBreaker
	rotateMax int
}

func NewLogAgent(baseDir string) *LogAgent {
	return &LogAgent{
		baseDir:   baseDir,
		cb:        NewCircuitBreaker(3, 30*time.Second),
		rotateMax: 5,
	}
}

func (la *LogAgent) resolveLogPath(name string) (string, error) {
	cleaned := filepath.Clean(name)
	if filepath.IsAbs(cleaned) {
		return "", fmt.Errorf("absolute paths not allowed")
	}
	fullPath := filepath.Join(la.baseDir, cleaned)
	// Verify the resolved path is within baseDir
	resolved, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}
	absBase, err := filepath.Abs(la.baseDir)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absBase, resolved)
	if err != nil || len(rel) > 2 && rel[:2] == ".." {
		return "", fmt.Errorf("path traversal detected")
	}
	return resolved, nil
}

func (la *LogAgent) RotateLog(name string) error {
	return la.cb.Execute(func() error {
		logPath, err := la.resolveLogPath(name)
		if err != nil {
			return err
		}
		// Rotate existing logs
		for i := la.rotateMax - 1; i >= 1; i-- {
			src := fmt.Sprintf("%s.%d", logPath, i)
			dst := fmt.Sprintf("%s.%d", logPath, i+1)
			os.Rename(src, dst)
		}
		// Move current log to .1
		os.Rename(logPath, logPath+".1")
		// Create fresh log file
		f, err := os.Create(logPath)
		if err != nil {
			return err
		}
		f.Close()
		return nil
	})
}

func (la *LogAgent) WriteLog(name string, data []byte) error {
	return la.cb.Execute(func() error {
		logPath, err := la.resolveLogPath(name)
		if err != nil {
			return err
		}
		// Check if path is a symlink before writing
		info, err := os.Lstat(logPath)
		if err == nil && info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("symlink detected, refusing to write")
		}
		f, err := os.OpenFile(logPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
		if err != nil {
			return err
		}
		defer f.Close()
		_, err = f.Write(data)
		return err
	})
}

func (la *LogAgent) CleanupOldLogs(name string) error {
	return la.cb.Execute(func() error {
		logPath, err := la.resolveLogPath(name)
		if err != nil {
			return err
		}
		for i := la.rotateMax; i >= 1; i-- {
			target := fmt.Sprintf("%s.%d", logPath, i)
			info, statErr := os.Stat(target)
			if statErr != nil {
				continue
			}
			if time.Since(info.ModTime()) > 7*24*time.Hour {
				os.Remove(target)
			}
		}
		return nil
	})
}

func main() {
	agent := NewLogAgent("/var/log/myagent")
	agent.WriteLog("app.log", []byte("service started\n"))
	agent.RotateLog("app.log")
	agent.CleanupOldLogs("app.log")
}
